def areEquivalent(a, b):
    """
    Check if the sum of divisors of a and b are the same.

    Parameters:
        a (int): First number
        b (int): Second number

    Returns:
        bool: True if the sum of divisors are the same, False otherwise.
    """
    def sum_divisors(n):
        if n <= 0:
            return 0
        total = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                total += i
                if n // i != i:
                    total += n // i
        return total

    return sum_divisors(a) == sum_divisors(b)
