def get_Odd_Occurrence(sequence):
    """
    Returns the element that occurs an odd number of times in the sequence.

    If multiple elements have the same odd count, the first one found is returned.
    If multiple elements have the same odd count, the one with the smallest value is returned.
    """
    # Count occurrences of each element
    counts = {}
    for element in sequence:
        if element in counts:
            counts[element] += 1
        else:
            counts[element] = 1

    # Filter elements that have an odd count
    odd_counts = [element for element, count in counts.items() if count % 2 == 1]

    # If there are multiple elements with odd counts, return the smallest one
    return min(odd_counts)
