def sum_div(n):
    """
    Returns the sum of all divisors of a number.

    Args:
        n (int): The number to find divisors for.

    Returns:
        int: The sum of all divisors.
    """
    if n < 0:
        return sum_div(abs(n))

    # Start from the first divisor that is greater than the square root
    # to avoid double counting the square root itself.
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            return i + n // i
    return sum_div(n)
